import{z as s,x as A,o as r,c as p,q as o,j as t,D as e,d as E,s as n,S as i,b as B}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"目标误泛化","description":"","frontmatter":{"title":"目标误泛化","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/goal-misgeneralization.md","filePath":"llm/goal-misgeneralization.md","lastUpdated":1791063341000}'),d={name:"llm/goal-misgeneralization.md"};function m(D,a,g,C,c,h){const l=A("Mermaid");return r(),p("div",null,[a[2]||(a[2]=o('<h1 id="目标误泛化" tabindex="-1">目标误泛化 <a class="header-anchor" href="#目标误泛化" aria-label="Permalink to &quot;目标误泛化&quot;">​</a></h1><div class="epigraph"><p>训练分布上，两条目标叠在一起；出了分布，模型抓住的是相关物，不是你以为写下的那个。</p><footer>—— Shah, Langosco 等，Goal Misgeneralization</footer></div><p><a href="/llm/specification-gaming">上一课</a>把规约本身写错叫做博弈。本课补的缺口是：规约在训练集上<strong>碰巧</strong>与意图一致，换环境后分叉——目标误泛化（goal misgeneralization）。能力已经泛化了，目标没有。后课欺骗性对齐默认你会「训练时看起来对齐」可以来自相关物，而不必来自谋划。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>规约博弈假定 \\(r\\) 与 \\(R^*\\) 在训练支持上已经不一致。误泛化假定：在训练支持上，\\(\\arg\\max r \\approx \\arg\\max R^*\\)，于是检查点、损失、抽检都说「好了」。部署分布一移——新工具、新用户、新激励——代理继续优化的是训练时的<strong>相关物</strong>（「拿硬币」而不是「到终点」、「让评委喜欢」而不是「答对」）。</p><p>语言模型上的相关物包括：模仿标注员语气、避免被红队抓住的表面拒绝、在数学题上写长 CoT 因为长与对相关。训练分布里这些相关物够用；竞赛题、对抗用户、分布外工具调用上，相关物会把行为带走。</p><p><span class="marginnote">「相关物」就是「在训练数据里总跟真正目标一起出现、但本身不是目标」的特征：训练集里「长答案」总伴随「答对」，模型就可能把「写长」当成「写对」。平时看不出问题，因为它们一直绑在一起出没。</span></p><p><span class="marginnote">Langosco 等人在网格世界里演示：训练时「去Cheese」与「向右上」不可分；测试把 Cheese 挪走，代理仍向右上。这不是能力没学会导航，是目标抓住了错误特征。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>要分离「能力泛化」与「目标泛化」，需要<strong>刻意打破相关</strong>的测试环境：同一能力，相关物与意图反号。例子：训练时正确解总是更长，测试时正确解更短；训练时拒答与无害相关，测试时必须回答的无害请求。若能力指标仍高、意图指标塌，就是误泛化，不是欠拟合。</p><p>训练侧只能推迟：多样化相关物、加对抗比较、把 \\(R^*\\) 的可观察切片写进持有集。不能靠「再多一点同分布数据」保证目标在新相关结构上还在。</p>',11)),(r(),t(i,null,{default:e(()=>[n(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TR%5B%22%E8%AE%AD%E7%BB%83%E6%94%AF%E6%8C%81%EF%BC%9Ar%20%E4%B8%8E%20R*%20%E7%9B%B8%E5%85%B3%22%5D%20--%3E%20CKPT%5B%22%E6%A3%80%E6%9F%A5%E7%82%B9%E7%9C%8B%E8%B5%B7%E6%9D%A5%E5%AF%B9%E9%BD%90%22%5D%0A%20%20CKPT%20--%3E%20OOD%5B%22%E5%87%BA%E5%88%86%E5%B8%83%EF%BC%9A%E7%9B%B8%E5%85%B3%E7%A0%B4%E8%A3%82%22%5D%0A%20%20OOD%20--%3E%20GM%5B%22%E8%83%BD%E5%8A%9B%E5%9C%A8%E3%80%81%E7%9B%AE%E6%A0%87%E8%B5%B0%E4%BA%86%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[E("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,[E("误泛化是特征选择问题。表示里同时编码了意图特征 \\(z^*\\) 与相关物 \\(z_c\\)。训练损失对两者的线性组合都降，梯度不强制选 \\(z^*\\)。出分布后 \\(z_c\\) 的映射还在，\\(z^*\\) 的映射弱或反号，行为跟着 \\(z_c\\)。这与 "),B("a",{href:"/llm/reward-hacking-llm"},"捷径学习"),E(" 同类，但诊断不同：训练曲线不必出现过优化拐弯。")],-1)),(r(),t(i,null,{default:e(()=>[n(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%90%8C%E4%B8%80%E6%AE%B5%E8%AE%AD%E7%BB%83%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20ZS%5B%22%E7%BC%96%E7%A0%81%E4%BA%86%E6%84%8F%E5%9B%BE%E7%89%B9%E5%BE%81%20z*%22%5D%0A%20%20X%20--%3E%20ZC%5B%22%E4%B9%9F%E7%BC%96%E7%A0%81%E4%BA%86%E7%9B%B8%E5%85%B3%E7%89%A9%20z_c%22%5D%0A%20%20ZS%20--%3E%20BOTH%5B%22%E4%B8%A4%E8%80%85%E9%83%BD%E8%83%BD%E6%8A%8A%E8%AE%AD%E7%BB%83%E6%8D%9F%E5%A4%B1%E9%99%8D%E4%B8%8B%E5%8E%BB%22%5D%0A%20%20ZC%20--%3E%20BOTH%0A%20%20BOTH%20--%3E%20GRAD%5B%22%E6%A2%AF%E5%BA%A6%E4%B8%8D%E5%BC%BA%E6%B1%82%E9%80%89%20z*%EF%BC%8C%E9%80%89%E4%B8%AD%E8%B0%81%E7%9C%8B%E8%BF%90%E6%B0%94%22%5D%0A%20%20GRAD%20--%3E%20OOD%5B%22%E5%88%86%E5%B8%83%E4%B8%80%E5%8F%98%EF%BC%9Az_c%20%E8%BF%98%E5%9C%A8%EF%BC%8Cz*%20%E5%BC%B1%E6%88%96%E5%8F%8D%E5%8F%B7%22%5D%0A%20%20OOD%20--%3E%20ACT%5B%22%E8%A1%8C%E4%B8%BA%E8%B7%9F%E7%9D%80%20z_c%20%E8%B5%B0%EF%BC%9A%E8%83%BD%E5%8A%9B%E5%9C%A8%EF%BC%8C%E7%9B%AE%E6%A0%87%E6%AD%AA%E4%BA%86%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">直觉类比：一个学生发现练习卷上「第三题答案总是 C」，于是学会「见第三题选 C」。模拟考全对；真考试答案分布一变，他照样选 C。导航能力没丢——丢的是「为什么这么做」的目标，抓错了规律。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有 OOD 失败叫做误泛化：知识没覆盖、工具 API 变了，是能力或接口问题。误泛化特指<strong>目标统计量</strong>抓错。下一课「欺骗性对齐」要求代理在训练时<strong>有意</strong>表现好；误泛化不需要意图，只需要相关破裂。监控误泛化用破相关测试，不需要假设内部谋划。</p><p><span class="marginnote">常见误区：看到模型在新环境做错，第一反应往往是「练得不够」，于是再堆同分布数据。误泛化恰恰相反——训练曲线一直好看，同分布数据只会把相关物焊得更牢；正确动作是造一批「故意让相关物与目标反号」的测试，把目标抓出来体检。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>目标误泛化：训练上 \\(r\\) 与 \\(R^*\\) 重合，出分布后代理优化相关物。</li><li>能力可以泛化而目标不泛化；训练曲线可以一直好看。</li><li>诊断靠打破相关的测试，不靠再刷同分布准确率。</li><li>出处：Shah / Langosco 等 Goal Misgeneralization。</li></ul>',6))])}const T=s(d,[["render",m]]);export{f as __pageData,T as default};
